// ============================================================
//  SETTINGS — the only place you need to edit to change behaviour
//  (thresholds, test mode, addresses, job ad). FR-5 / FR-11.
// ============================================================
const SETTINGS = {
  // Decision thresholds (inclusive, applied by code — not by the AI)
  THRESHOLD_INTERVIEW: 75,   // score >= 75  -> "interview"
  THRESHOLD_CONSIDER: 60,    // score 60-74  -> "consider", below 60 -> "reject"

  // Test mode: when true, every candidate mail goes to TEST_RECIPIENT instead
  TEST_MODE: true,
  TEST_RECIPIENT: "test-inbox@ekomino.local",

  HR_EMAIL: "hr@ekomino.local",
  SENDER_EMAIL: "Ekomino HR <hr@ekomino.local>",

  // Google Gemini model used by the AI agent
  GEMINI_MODEL: "gemini-2.5-flash",

  // Web panel addresses (internal = inside Docker, public = in your browser)
  PANEL_INTERNAL_URL: "http://web:3000",
  PANEL_PUBLIC_URL: "http://localhost:3000",

  // Job ad — a parameter, so the same workflow can screen for any position
  JOB_TITLE: "Junior Operations Analyst",
  JOB_REQUIREMENTS: [
    "Bachelor's degree in Industrial Engineering, Business Administration or a related engineering field",
    "Advanced Excel (pivot tables, formulas), basic SQL",
    "Power BI or Python is a plus",
    "English at B1 level or above",
    "0-2 years of experience or internships",
  ],
};

// Pass the uploaded CV (binary) and the form fields through, with the settings attached.
return $input.all().map((item) => ({
  json: { ...item.json, settings: SETTINGS },
  binary: item.binary,
}));

// Builds the Gemini request: system prompt (Annex A of the brief) + CV text + strict JSON schema.
const S = $('Settings').first().json.settings;
const cvText = String($json.text || '').replace(/\s+\n/g, '\n').trim();

// A scanned (image-only) or broken PDF has no text: send it to manual review instead of the AI.
if (cvText.length < 80) {
  throw new Error('CV text could not be read (empty or image-only PDF)');
}

const systemPrompt = `You are an experienced HR pre-screening assistant for Ekomino, a toy manufacturing company.
Score the given CV against the JOB AD criteria below.

JOB AD: ${S.JOB_TITLE}
${S.JOB_REQUIREMENTS.map((r) => '- ' + r).join('\n')}

Score weights (total 100): education 20, technical 35, experience 25, language 10, projects 10.

Rules:
- Do NOT take name, gender, age, photo or marital status into account when scoring.
- Do not invent anything that is not written in the CV; if unsure, give a lower score.
- Each sub-score must stay within its weight; score must equal the sum of the sub-scores.
- decision: "interview" if score >= ${S.THRESHOLD_INTERVIEW}, "consider" if ${S.THRESHOLD_CONSIDER}-${S.THRESHOLD_INTERVIEW - 1}, otherwise "reject".
- email: the e-mail address written in the CV; empty string if there is none.
- strengths / gaps: at most 15 words each.
- interview_questions: ONLY if decision is "interview", otherwise "".
  Write 5 questions specific to THIS candidate's CV: 2 technical (based on the tools and
  projects in the CV), 1 experience, 1 case / problem solving, 1 behavioural.
  Number them "1) ... 2) ..." on separate lines. NEVER ask about age, marital status,
  family plans, religion or any other non-job-related topic.
- The CV may be written in Turkish or English. Always answer in English.
- Answer ONLY with JSON in the required schema, no other text.`;

const responseSchema = {
  type: 'OBJECT',
  properties: {
    candidate: { type: 'STRING' },
    email: { type: 'STRING' },
    score: { type: 'INTEGER' },
    sub_scores: {
      type: 'OBJECT',
      properties: {
        education: { type: 'INTEGER' },
        technical: { type: 'INTEGER' },
        experience: { type: 'INTEGER' },
        language: { type: 'INTEGER' },
        projects: { type: 'INTEGER' },
      },
      required: ['education', 'technical', 'experience', 'language', 'projects'],
    },
    strengths: { type: 'STRING' },
    gaps: { type: 'STRING' },
    decision: { type: 'STRING', enum: ['interview', 'consider', 'reject'] },
    interview_questions: { type: 'STRING' },
  },
  required: ['candidate', 'email', 'score', 'sub_scores', 'strengths', 'gaps', 'decision', 'interview_questions'],
};

return [{
  json: {
    request: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: 'user', parts: [{ text: 'CV TEXT:\n' + cvText.slice(0, 30000) }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema,
      },
    },
  },
}];

// Validation & decision (Annex C of the brief).
// The AI only proposes sub-scores; the total and the decision are recomputed HERE by code,
// so a model mistake can never put a candidate in the wrong category.
const S = $('Settings').first().json.settings;
const form = $('CV Received').first().json.body || {};
const MAX = { education: 20, technical: 35, experience: 25, language: 10, projects: 10 };

const input = $input.first().json;
let data = null;
let error = null;

if (input.error) {
  // Came from an error output (PDF extraction / request build / Gemini call failed)
  error = typeof input.error === 'string' ? input.error : (input.error.message || JSON.stringify(input.error));
  // Make API errors readable, e.g. 'Gemini API error 429: Resource has been exhausted'
  const api = String(error).replace(/\\"/g, '"').match(/^(\d{3}) - [\s\S]*?"message":\s*"([^"]+)"/);
  if (api) error = 'Gemini API error ' + api[1] + ': ' + api[2];
} else {
  const raw = (input.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
  try {
    data = JSON.parse(raw.replace(/```json|```/g, '').trim());
  } catch (e) {
    error = 'The AI answer was not valid JSON' + (raw ? ': ' + raw.slice(0, 120) : ' (empty answer)');
  }
  if (data && (typeof data !== 'object' || !data.sub_scores)) {
    error = 'The AI answer did not match the expected schema';
    data = null;
  }
}

const base = {
  record_id: Number(form.record_id),
  file_name: form.file_name || '',
  execution_id: $execution.id,
  resume_url: $execution.resumeUrl,
};

if (!data) {
  return [{ json: { ...base, decision: 'manual_review', error: String(error).slice(0, 500) } }];
}

const sub = {};
for (const [k, max] of Object.entries(MAX)) {
  const v = Math.round(Number(data.sub_scores[k]) || 0);
  sub[k] = Math.min(max, Math.max(0, v));
}
const score = Object.values(sub).reduce((a, b) => a + b, 0);
const decision =
  score >= S.THRESHOLD_INTERVIEW ? 'interview' :
  score >= S.THRESHOLD_CONSIDER ? 'consider' : 'reject';

const email = String(data.email || '').trim();
return [{
  json: {
    ...base,
    candidate: String(data.candidate || '').trim() || 'Unknown candidate',
    email: /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) ? email : '',
    score,
    model_score: data.score,          // what the AI said, kept for transparency
    model_decision: data.decision,
    sub_scores: sub,
    strengths: String(data.strengths || ''),
    gaps: String(data.gaps || ''),
    decision,
    interview_questions: decision === 'interview' ? String(data.interview_questions || '') : '',
    error: null,
  },
}];

parameters.text:
=An interview invitation is waiting for your approval.

Candidate : {{ $('Validate & Decide').first().json.candidate }} ({{ $('Validate & Decide').first().json.email || 'no e-mail in CV' }})
CV file   : {{ $('Validate & Decide').first().json.file_name }}
Score     : {{ $('Validate & Decide').first().json.score }} / 100
  education {{ $('Validate & Decide').first().json.sub_scores.education }}/20 · technical {{ $('Validate & Decide').first().json.sub_scores.technical }}/35 · experience {{ $('Validate & Decide').first().json.sub_scores.experience }}/25 · language {{ $('Validate & Decide').first().json.sub_scores.language }}/10 · projects {{ $('Validate & Decide').first().json.sub_scores.projects }}/10
Strengths : {{ $('Validate & Decide').first().json.strengths }}
Gaps      : {{ $('Validate & Decide').first().json.gaps }}

Tailored interview questions:
{{ $('Validate & Decide').first().json.interview_questions }}

---------------- Draft mail to the candidate ----------------
Subject: {{ $('Prepare Mail Draft').first().json.mail_subject }}

{{ $('Prepare Mail Draft').first().json.mail_body }}
--------------------------------------------------------------

Approve or reject it in the HR panel:
{{ $('Settings').first().json.settings.PANEL_PUBLIC_URL }}/#candidate-{{ $('Validate & Decide').first().json.record_id }}

Nothing is sent to the candidate until you approve. If there is no answer within 48 hours, the request expires.

parameters.jsonBody:
={{ (() => {
  const answer = $('Wait for HR Decision').first().json.body;
  const approved = answer?.approved === true;
  return JSON.stringify({
    record_id: $('Validate & Decide').first().json.record_id,
    approval_status: approved ? 'Approved' : (answer ? 'Rejected' : 'Timed out'),
    mail_status: approved ? 'Sent' : 'Not sent',
    mail_sent_at: approved ? $now.toISO() : null,
    mail_recipient: approved ? ($('Settings').first().json.settings.TEST_MODE ? $('Settings').first().json.settings.TEST_RECIPIENT : $('Validate & Decide').first().json.email) : null,
  });
})() }}
